insert into public.profile select * from jsonb_populate_recordset(null::public.profile,'[{"id":"0119fa94-e8b5-50e1-ac8f-4c47a95659ac","slug":"anshul-sharma","name":"Anshul Sharma","title":"Data Science Manager","headline":"Making intelligence\nwork in the real world.","introduction":"I build AI products from business problem to production. My work brings together generative AI, machine learning, and the engineering that makes them useful.","about":"A developer turned data scientist, I work across the full lifecycle of an AI product: understanding the problem, building the data foundations, and taking models into production. My work spans automotive, enterprise knowledge, seller productivity, and cloud infrastructure.","location":"Dubai, UAE","email":"anshuls235@gmail.com","image_url":"assets/portrait.webp","resume_url":"resume.pdf","current_focus":"Generative AI · MLOps · Decision intelligence","status":"published","sort_order":0,"created_at":"2026-11-01T00:00:00+00:00","updated_at":"2026-11-01T00:00:00+00:00"}]'::jsonb) on conflict (id) do nothing;
insert into public.projects select * from jsonb_populate_recordset(null::public.projects,'[{"id":"873cb3bb-e76f-5cfc-bbf8-362569777ef2","slug":"automall-ai-search","title":"A more natural way to find a car.","category":"Generative AI","summary":"Multilingual AI search for Automall, connecting customer intent with vehicle discovery.","description":"An end-to-end English and Arabic car search system for Automall using LangGraph, FastAPI, and Azure OpenAI. Databricks analytics pipelines and Power BI dashboards support business monitoring.","role":"Data Science Manager","organization":"Al-Futtaim Automotive","start_date":null,"end_date":null,"problem":"Help customers explore car inventory in English and Arabic using natural language.","approach":"Combine intent classification, multi-parser NLP routing, and progressive search relaxation. Automate analytics with Databricks and Power BI.","responsibilities":["Built the end-to-end multilingual search system and its automated analytics pipelines."],"outcomes":["Reported in the July 2026 CV: live since April 2026, with 10 orders at under US$70 total operating cost."],"technologies":["LangGraph","FastAPI","Azure OpenAI","Databricks","Power BI"],"image_url":null,"image_alt":null,"visual_kind":"search","featured":true,"status":"published","sort_order":0,"created_at":"2026-11-01T00:00:00+00:00","updated_at":"2026-11-01T12:38:09.305399+00:00"},{"id":"fb3c1746-efdb-502a-ad88-f8e08c247388","slug":"enterprise-knowledge","title":"Putting enterprise knowledge within reach.","category":"Generative AI","summary":"Retrieval-augmented answers built around internal enterprise documents.","description":"A company-specific question-answering chatbot using Mistral 7B and retrieval-augmented generation, developed during my work at Gartner.","role":"Senior Data Scientist","organization":"Gartner","start_date":null,"end_date":null,"problem":"Make internal knowledge easier to access through a conversational interface.","approach":"Combine enterprise document retrieval with a fine-tuned Mistral 7B model.","responsibilities":[],"outcomes":[],"technologies":["Mistral 7B","RAG","LangChain","Hugging Face"],"image_url":null,"image_alt":null,"visual_kind":"retrieval","featured":true,"status":"published","sort_order":1,"created_at":"2026-11-01T00:00:00+00:00","updated_at":"2026-11-01T00:00:00+00:00"},{"id":"a007224a-453b-5ed4-9664-0bde358d9c0d","slug":"ml-pipeline-optimization","title":"Less waiting. More working with data.","category":"ML engineering","summary":"Optimizing PySpark data pipelines and introducing MLflow-based model operations.","description":"Data pipeline optimization and an MLOps framework developed at Gartner. The original résumé records a reduction in processing time from 12 hours to 12 minutes.","role":"Senior Data Scientist","organization":"Gartner","start_date":null,"end_date":null,"problem":"Long-running data processing slowed the ML workflow.","approach":"Optimize PySpark pipelines and use MLflow to support model lifecycle management and monitor drift.","responsibilities":[],"outcomes":["Data processing reduced from 12 hours to 12 minutes, as recorded in the source résumé."],"technologies":["PySpark","MLflow","Python","MLOps"],"image_url":null,"image_alt":null,"visual_kind":"pipeline","featured":true,"status":"published","sort_order":2,"created_at":"2026-11-01T00:00:00+00:00","updated_at":"2026-11-01T00:00:00+00:00"},{"id":"35d445d6-392e-511a-9fe7-6f3773bcf625","slug":"automall-conversational-ai","title":"Automall, in a conversation.","category":"Generative AI","summary":"Conversational vehicle discovery and customer support through WhatsApp.","description":"A WhatsApp AI chatbot for Automall using LangGraph and Infobip, with intent classification, FAQ retrieval, live agent handoff, sell-car flow, and SAP C4C CRM integration.","role":"Data Science Manager","organization":"Al-Futtaim Automotive","start_date":null,"end_date":null,"problem":"Bring vehicle discovery and common customer questions into a conversational channel.","approach":"Orchestrate conversational flows with LangGraph, connect WhatsApp through Infobip, and integrate with SAP C4C. Use Databricks pipelines and Power BI for monitoring.","responsibilities":[],"outcomes":["Reported in the July 2026 CV: live since March 2026, with 25 orders at under US$200 cumulative cost."],"technologies":["LangGraph","Infobip","Azure OpenAI","SAP C4C","Databricks"],"image_url":null,"image_alt":null,"visual_kind":"retrieval","featured":false,"status":"published","sort_order":3,"created_at":"2026-11-01T00:00:00+00:00","updated_at":"2026-11-01T12:38:09.305399+00:00"},{"id":"2cfd36c0-1665-5ab9-a998-66bbd5554e3d","slug":"expected-credit-loss","title":"Models for better risk decisions.","category":"Machine learning","summary":"Expected Credit Loss modeling for automotive finance.","description":"Expected Credit Loss models for automotive operating and financial lease portfolios, combining probability of default modeling with analytical loss-given-default and exposure-at-default estimation.","role":"Data Science Manager","organization":"Al-Futtaim Automotive","start_date":null,"end_date":null,"problem":"Support risk stakeholders with a more granular view of the loan portfolio.","approach":"Engineer features in Databricks, train the probability-of-default model with H2O Driverless AI, and estimate LGD and EAD analytically for credit risk reporting.","responsibilities":[],"outcomes":[],"technologies":["Databricks","H2O Driverless AI","AutoML","Credit risk","Python"],"image_url":null,"image_alt":null,"visual_kind":"chart","featured":false,"status":"published","sort_order":4,"created_at":"2026-11-01T00:00:00+00:00","updated_at":"2026-11-01T00:00:00+00:00"},{"id":"28cd4d61-9a00-5bf5-8d6a-eda1cd8737e3","slug":"recruitment-studio","title":"A structured first pass at hiring.","category":"Generative AI","summary":"LLM-powered résumé screening and scoring for Recruitment Studio.","description":"A résumé screening and scoring tool built at Gartner using Mixtral 8x7B and Llama2 70B.","role":"Senior Data Scientist","organization":"Gartner","start_date":null,"end_date":null,"problem":"Reduce the manual effort involved in reviewing candidate information.","approach":"Use large language models with structured hiring inputs to support résumé screening.","responsibilities":[],"outcomes":[],"technologies":["Mixtral 8x7B","Llama2 70B","Python","Hugging Face"],"image_url":null,"image_alt":null,"visual_kind":"retrieval","featured":false,"status":"published","sort_order":5,"created_at":"2026-11-01T00:00:00+00:00","updated_at":"2026-11-01T00:00:00+00:00"},{"id":"ad38a989-0771-5d0a-90cd-0de14f2507f9","slug":"covid19-dashboard","title":"A public-health data story.","category":"Data visualization","summary":"An open-source dashboard exploring COVID-19 data in India.","description":"A personal learning project built with Python and Dash, inspired by the Aarogya Setu dashboard. The source repository is public; the historical Heroku deployment is not presented as an active demo.","role":"Personal project","organization":null,"start_date":null,"end_date":null,"problem":"Explore public COVID-19 data through interactive visualization.","approach":"Build an interactive dashboard with Python and Dash.","responsibilities":[],"outcomes":[],"technologies":["Python","Dash","Plotly"],"image_url":null,"image_alt":null,"visual_kind":"chart","featured":false,"status":"published","sort_order":6,"created_at":"2026-11-01T00:00:00+00:00","updated_at":"2026-11-01T00:00:00+00:00"},{"id":"a6518117-5e49-564d-bff6-ac4b4fdb0c8d","slug":"freshness-detector","title":"A small experiment in computer vision.","category":"Machine learning","summary":"Classifying fruit freshness, with the limits of the training data made explicit.","description":"A public fruit-freshness detector for apples, bananas, and oranges. The repository documents its white-background image requirements and training-data limitations.","role":"Personal project","